def run_causal_discovery(X: np.ndarray) -> np.ndarray:
    from sklearn.linear_model import LassoLarsIC
    from sklearn.utils import check_array

    X = check_array(X)
    n, d = X.shape
    eps = 1e-8
    Z = (X - X.mean(0)) / (X.std(0) + eps)

    def dep(a, b):
        a = (a - a.mean()) / (a.std() + eps)
        b = (b - b.mean()) / (b.std() + eps)
        return abs((np.tanh(a) * b).mean()) + abs((a * np.tanh(b)).mean()) + 0.5 * abs(((a ** 3) * b).mean())

    def resid(y, x):
        return y - x * ((y @ x) / (x @ x + eps))

    def greedy():
        U, Xw, K = list(range(d)), Z.copy(), []
        while len(U) > 1:
            scores = [sum(dep(Xw[:, j], resid(Xw[:, i], Xw[:, j])) for i in range(len(U)) if i != j) for j in range(len(U))]
            j = int(np.argmin(scores))
            xj = Xw[:, j]
            K.append(U.pop(j))
            Xw = np.column_stack([resid(Xw[:, i], xj) for i in range(Xw.shape[1]) if i != j]) if len(U) else np.empty((n, 0))
        return K + U

    def pairwise():
        win = np.zeros(d)
        for i in range(d):
            for j in range(i + 1, d):
                s_ij = dep(Z[:, i], resid(Z[:, j], Z[:, i]))
                s_ji = dep(Z[:, j], resid(Z[:, i], Z[:, j]))
                win[i] += s_ji - s_ij
                win[j] += s_ij - s_ji
        return list(np.argsort(-win))

    def oscore(K):
        E = np.column_stack([Z[:, k] - (Z[:, K[:t]] @ np.linalg.lstsq(Z[:, K[:t]], Z[:, k], rcond=None)[0] if t else 0.0) for t, k in enumerate(K)])
        return sum(dep(E[:, a], E[:, b]) for a in range(d) for b in range(a))

    K1, K2 = greedy(), pairwise()
    s1, s2 = oscore(K1), oscore(K2)
    r1, r2 = np.empty(d), np.empty(d)
    r1[K1], r2[K2] = np.arange(d), np.arange(d)
    K3 = list(np.argsort(r1 / (s1 + eps) + r2 / (s2 + eps)))
    K = min((K1, K2, K3), key=oscore)

    B = np.zeros((d, d))
    for t, k in enumerate(K):
        if t == 0:
            continue
        pa = np.array(K[:t])
        P, y = Z[:, pa], Z[:, k]
        try:
            coef = LassoLarsIC(criterion='bic', fit_intercept=False).fit(P, y).coef_
        except Exception:
            coef = np.linalg.lstsq(P, y, rcond=None)[0]
            coef[np.abs(coef) < (0.05 + np.sqrt(np.log(d + 1) / (n + 1)))] = 0.0
        sel = np.abs(coef) > 1e-10
        if np.any(sel):
            B[k, pa[sel]] = np.linalg.lstsq(P[:, sel], y, rcond=None)[0]
    return B
